import csv
import math

# Read stop service intensity data
stop_data = {}
with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        stop_data[stop_id] = {
            'n_departures': int(row['n_departures']),
            'n_routes': int(row['n_routes'])
        }

# Read output file
output_rows = []
with open('outputs/t10_accessibility_scores.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        output_rows.append(row)

# Read input poi file to verify distances
with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    poi_data = {row['qid']: row for row in reader}

# Verify each row
errors = []
for row in output_rows:
    qid = row['qid']
    if qid not in poi_data:
        errors.append(f'{qid}: not in poi_data')
        continue

    input_row = poi_data[qid]

    # Check distance matches
    if float(row['distance_m']) != float(input_row['distance_m']):
        errors.append(f'{qid}: distance mismatch')

    # Check n_departures and n_routes match stop data
    stop_id = input_row['nearest_stop_id']
    if stop_id not in stop_data:
        errors.append(f'{qid}: stop_id not in stop_data')
        continue

    expected_departures = stop_data[stop_id]['n_departures']
    expected_routes = stop_data[stop_id]['n_routes']

    if int(row['n_departures']) != expected_departures:
        errors.append(f'{qid}: n_departures mismatch')
    if int(row['n_routes']) != expected_routes:
        errors.append(f'{qid}: n_routes mismatch')

if errors:
    for e in errors:
        print(e)
else:
    print('All rows verified successfully!')
""}

