import csv

# Check for any fields containing commas, quotes, or newlines
with open('outputs/t10_accessibility_scores.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)

    issues = []
    for i, row in enumerate(reader):
        for j, field in enumerate(row):
            # Check if field contains comma, quote, or newline
            if ',' in field or '\"' in field or '\n' in field:
                issues.append(f'Row {i+2}, Col {j}: {repr(field)}')
            # Check if field is quoted when it doesn't need to be
            if field.startswith('\"') and field.endswith('\"'):
                # Check if the content actually needs quoting
                content = field[1:-1]
                if ',' not in content and '\"' not in content and '\n' not in content:
                    # This is unnecessarily quoted but still valid
                    pass

if issues:
    for issue in issues[:5]:
        print(issue)
else:
    print('No RFC 4180 quoting issues found')
""}

